// Package toml contains the TOML decoder and its tagged value model.
package toml

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// Value is the JSON representation of a TOML scalar value.
type Value struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// Document is the JSON representation of a TOML document.
type Document map[string]any

// Decode parses a TOML document and returns its tagged representation.
func Decode(input string) (Document, error) {
	if !utf8.ValidString(input) {
		return nil, fmt.Errorf("invalid UTF-8")
	}
	if err := validateInputBytes(input); err != nil {
		return nil, err
	}
	input = strings.ReplaceAll(input, "\r\n", "\n")
	input = strings.ReplaceAll(input, "\r", "\n")
	document := Document{}
	lines := strings.Split(input, "\n")
	for lineNumber := 0; lineNumber < len(lines); lineNumber++ {
		line := lines[lineNumber]
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		eq := strings.IndexByte(line, '=')
		if eq < 0 {
			return nil, fmt.Errorf("line %d: expected key-value pair", lineNumber+1)
		}
		key := strings.TrimSpace(line[:eq])
		if key == "" {
			return nil, fmt.Errorf("line %d: invalid key-value pair", lineNumber+1)
		}
		raw := strings.TrimLeft(line[eq+1:], " \t")
		var value Value
		var err error
		if strings.HasPrefix(raw, "\"\"\"") || strings.HasPrefix(raw, "'''") {
			quote := raw[:3]
			parts := []string{raw}
			for !hasMultilineEnd(strings.Join(parts, "\n"), quote) {
				lineNumber++
				if lineNumber >= len(lines) {
					return nil, fmt.Errorf("line %d: unterminated multiline string", lineNumber)
				}
				parts = append(parts, lines[lineNumber])
			}
			raw = strings.Join(parts, "\n")
			value, _, err = decodeString(raw)
		} else {
			for hasLineContinuation(raw) {
				lineNumber++
				if lineNumber >= len(lines) {
					return nil, fmt.Errorf("line %d: unterminated line continuation", lineNumber)
				}
				raw += "\n" + lines[lineNumber]
			}
			raw = stripComment(raw)
			cleaned := strings.TrimSpace(raw)
			var end int
			value, end, err = decodeValue(cleaned)
			if err == nil && strings.TrimSpace(cleaned[end:]) != "" {
				err = fmt.Errorf("text after value")
			}
		}
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", lineNumber+1, err)
		}
		if _, exists := document[key]; exists {
			return nil, fmt.Errorf("line %d: duplicate key %q", lineNumber+1, key)
		}
		document[key] = value
	}
	return document, nil
}

// validateInputBytes applies the document-wide lexical restrictions before line
// parsing can accidentally treat a forbidden byte as whitespace or content.
func validateInputBytes(input string) error {
	lineHasToken := false
	for i := 0; i < len(input); i++ {
		c := input[i]
		switch {
		case c == '\n':
			lineHasToken = false
			continue
		case c == '\t' || c == ' ':
			continue
		case c == '\r':
			if i+1 < len(input) && input[i+1] == '\n' {
				i++
				lineHasToken = false
				continue
			}
			return fmt.Errorf("invalid carriage return")
		case c < 0x20 || c == 0x7f:
			return fmt.Errorf("invalid control character")
		}
		if c >= utf8.RuneSelf {
			r, width := utf8.DecodeRuneInString(input[i:])
			if r == '\u3000' && !lineHasToken || r == '\ufeff' || r == '\ufffd' {
				return fmt.Errorf("invalid non-ASCII whitespace or encoding marker")
			}
			i += width - 1
		}
		lineHasToken = true
	}
	return nil
}

func hasMultilineEnd(s, quote string) bool {
	_, end, err := decodeString(s)
	return err == nil && end > 0 && end <= len(s) && validCommentSuffix(s[end:])
}

func validCommentSuffix(s string) bool {
	s = strings.TrimLeft(s, " \t")
	return s == "" || strings.HasPrefix(s, "#")
}

func decodeValue(raw string) (Value, int, error) {
	if strings.HasPrefix(raw, "\"") || strings.HasPrefix(raw, "'") {
		return decodeString(raw)
	}
	return decodeScalar(raw)
}

func decodeString(raw string) (Value, int, error) {
	if strings.HasPrefix(raw, "\"\"\"") {
		return decodeQuoted(raw, '"', true)
	}
	if strings.HasPrefix(raw, "'''") {
		return decodeQuoted(raw, '\'', true)
	}
	if strings.HasPrefix(raw, "\"") {
		return decodeQuoted(raw, '"', false)
	}
	if strings.HasPrefix(raw, "'") {
		return decodeQuoted(raw, '\'', false)
	}
	return Value{}, 0, fmt.Errorf("invalid string")
}

func decodeQuoted(raw string, quote byte, multiline bool) (Value, int, error) {
	start := 1
	if multiline {
		start = 3
		if len(raw) > 3 && raw[3] == '\n' {
			start++
		}
	}
	var out strings.Builder
	for i := start; i < len(raw); {
		if multiline && raw[i] == quote {
			run := 0
			for i+run < len(raw) && raw[i+run] == quote {
				run++
			}
			if run >= 3 {
				if run > 5 {
					return Value{}, 0, fmt.Errorf("too many delimiter quotes")
				}
				out.WriteString(strings.Repeat(string(quote), run-3))
				return Value{Type: "string", Value: out.String()}, i + run, nil
			}
		}
		if !multiline && raw[i] == quote {
			return Value{Type: "string", Value: out.String()}, i + 1, nil
		}
		if raw[i] == quote && !multiline {
			return Value{}, 0, fmt.Errorf("unexpected quote in string")
		}
		if raw[i] == '\n' && !multiline {
			return Value{}, 0, fmt.Errorf("newline in basic string")
		}
		if raw[i] == '\\' && quote == '"' {
			if i+1 >= len(raw) {
				return Value{}, 0, fmt.Errorf("unterminated escape")
			}
			j := i + 1
			for j < len(raw) && (raw[j] == ' ' || raw[j] == '\t') {
				j++
			}
			if j < len(raw) && raw[j] == '\n' {
				i = j + 1
				for i < len(raw) && (raw[i] == ' ' || raw[i] == '\t' || raw[i] == '\n') {
					i++
				}
				continue
			}
			decoded, n, err := escape(raw[i:])
			if err != nil {
				return Value{}, 0, err
			}
			out.WriteString(decoded)
			i += n
			continue
		}
		if !validStringCharacter(raw[i], multiline) {
			return Value{}, 0, fmt.Errorf("invalid control character in string")
		}
		if raw[i] < utf8.RuneSelf {
			out.WriteByte(raw[i])
			i++
		} else {
			r, n := utf8.DecodeRuneInString(raw[i:])
			if r == utf8.RuneError && n == 1 {
				return Value{}, 0, fmt.Errorf("invalid UTF-8 in string")
			}
			out.WriteString(raw[i : i+n])
			i += n
		}
	}
	return Value{}, 0, fmt.Errorf("unterminated string")
}

func hasLineContinuation(raw string) bool {
	raw = strings.TrimRight(raw, " \t")
	if len(raw) == 0 || raw[len(raw)-1] != '\\' {
		return false
	}
	n := 0
	for i := len(raw) - 1; i >= 0 && raw[i] == '\\'; i-- {
		n++
	}
	return n%2 == 1
}

func validStringCharacter(c byte, multiline bool) bool {
	if c == '\t' || c >= 0x20 {
		return c != 0x7f || multiline
	}
	return multiline && c == '\n'
}

func escape(raw string) (string, int, error) {
	switch raw[1] {
	case 'b':
		return "\b", 2, nil
	case 't':
		return "\t", 2, nil
	case 'n':
		return "\n", 2, nil
	case 'f':
		return "\f", 2, nil
	case 'r':
		return "\r", 2, nil
	case '"':
		return "\"", 2, nil
		return "\"", 2, nil
	case '\\':
		return "\\", 2, nil
	case 'u':
		return unicodeEscape(raw, 4)
	case 'U':
		return unicodeEscape(raw, 8)
	default:
		return "", 0, fmt.Errorf("invalid escape sequence")
	}
}

func unicodeEscape(raw string, digits int) (string, int, error) {
	if len(raw) < digits+2 {
		return "", 0, fmt.Errorf("incomplete Unicode escape")
	}
	code, err := strconv.ParseUint(raw[2:digits+2], 16, 32)
	if err != nil || code > utf8.MaxRune || (code >= 0xd800 && code <= 0xdfff) {
		return "", 0, fmt.Errorf("invalid Unicode scalar escape")
	}
	return string(rune(code)), digits + 2, nil
}

func stripComment(raw string) string {
	quote := byte(0)
	escaped := false
	for i := 0; i < len(raw); i++ {
		if quote == '"' && escaped {
			escaped = false
			continue
		}
		if quote == '"' && raw[i] == '\\' {
			escaped = true
			continue
		}
		if raw[i] == '"' || raw[i] == '\'' {
			if quote == 0 {
				quote = raw[i]
			} else if quote == raw[i] {
				quote = 0
			}
		} else if raw[i] == '#' && quote == 0 {
			return raw[:i]
		}
	}
	return raw
}

func decodeScalar(raw string) (Value, int, error) {
	switch raw {
	case "true", "false":
		return Value{Type: "bool", Value: raw}, len(raw), nil
	case "inf", "+inf", "-inf", "nan", "+nan", "-nan":
		return Value{Type: "float", Value: raw}, len(raw), nil
	}
	if isIntegerToken(raw) {
		if err := validateInteger(raw); err != nil {
			return Value{}, 0, err
		}
		return Value{Type: "integer", Value: raw}, len(raw), nil
	}
	if isFloatToken(raw) {
		return Value{Type: "float", Value: raw}, len(raw), nil
	}
	return Value{}, 0, fmt.Errorf("invalid scalar")
}

func isIntegerToken(raw string) bool {
	if raw == "" {
		return false
	}
	start := 0
	if raw[0] == '+' || raw[0] == '-' {
		start = 1
	}
	if start == len(raw) {
		return false
	}
	if start+2 <= len(raw) && raw[start] == '0' {
		switch raw[start+1] {
		case 'x', 'o', 'b':
			return validDigits(raw[start+2:], baseForPrefix(raw[start+1]))
		}
	}
	return validDecimalDigits(raw[start:])
}

func baseForPrefix(prefix byte) int {
	switch prefix {
	case 'x':
		return 16
	case 'o':
		return 8
	default:
		return 2
	}
}

func validateInteger(raw string) error {
	cleaned := strings.ReplaceAll(raw, "_", "")
	start := 0
	if cleaned[0] == '+' || cleaned[0] == '-' {
		start++
	}
	base := 10
	digits := cleaned[start:]
	if len(digits) > 2 && digits[0] == '0' {
		base = baseForPrefix(digits[1])
		digits = digits[2:]
	}
	sign := ""
	if start > 0 {
		sign = cleaned[:start]
	}
	if _, err := strconv.ParseInt(sign+digits, base, 64); err != nil {
		return fmt.Errorf("invalid integer")
	}
	return nil
}

func validDecimalDigits(s string) bool {
	if len(s) == 0 || s[0] == '_' || s[len(s)-1] == '_' {
		return false
	}
	if s[0] == '0' && len(s) > 1 {
		return false
	}
	return validDigits(s, 10)
}

func validDigits(s string, base int) bool {
	if len(s) == 0 || s[0] == '_' || s[len(s)-1] == '_' {
		return false
	}
	previousUnderscore := false
	for i := 0; i < len(s); i++ {
		if s[i] == '_' {
			if previousUnderscore || i == 0 || i+1 == len(s) {
				return false
			}
			previousUnderscore = true
			continue
		}
		value := digitValue(s[i])
		if value < 0 || value >= base {
			return false
		}
		previousUnderscore = false
	}
	return true
}

func digitValue(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	default:
		return -1
	}
}

func isFloatToken(raw string) bool {
	if raw == "" {
		return false
	}
	start := 0
	if raw[0] == '+' || raw[0] == '-' {
		start++
	}
	if start == len(raw) || strings.ContainsAny(raw[start:], "xXoObB") {
		return false
	}
	body := raw[start:]
	dot := strings.IndexByte(body, '.')
	exp := strings.IndexAny(body, "eE")
	if dot < 0 && exp < 0 {
		return false
	}
	if dot >= 0 && exp >= 0 && exp < dot {
		return false
	}
	mantissa := body
	exponent := ""
	if exp >= 0 {
		mantissa, exponent = body[:exp], body[exp+1:]
		if exponent == "" {
			return false
		}
		if exponent[0] == '+' || exponent[0] == '-' {
			exponent = exponent[1:]
		}
		if !validDecimalDigitsNoLeadingRule(exponent) {
			return false
		}
	}
	if dot >= 0 {
		left, right := mantissa[:dot], mantissa[dot+1:]
		if !validDecimalDigits(left) || (right != "" && !validDigits(right, 10)) {
			return false
		}
		return right != "" || dot == len(mantissa)-1
	}
	return validDecimalDigitsNoLeadingRule(mantissa)
}

func validDecimalDigitsNoLeadingRule(s string) bool {
	return validDigits(s, 10)
}

package toml

import "testing"

func TestDecodeEmptyDocument(t *testing.T) {
	got, err := Decode("")
	if err != nil {
		t.Fatalf("Decode(empty) returned error: %v", err)
	}
	if got == nil {
		t.Fatal("Decode(empty) returned nil document")
	}
	if len(got) != 0 {
		t.Fatalf("Decode(empty) returned %v, want empty document", got)
	}
}

func TestDecodeInteger(t *testing.T) {
	got, err := Decode("answer = 42\n")
	if err != nil {
		t.Fatalf("Decode(integer) returned error: %v", err)
	}
	want := Value{Type: "integer", Value: "42"}
	if got["answer"] != want {
		t.Fatalf("Decode(integer) = %v, want %v", got["answer"], want)
	}
}

func TestDecodeMalformedArrayReturnsError(t *testing.T) {
	if _, err := Decode("answer = [\n"); err == nil {
		t.Fatal("Decode(malformed array) returned nil error")
	}
}

func TestDecodePreservesIntegerSpelling(t *testing.T) {
	got, err := Decode("answer = 1_000\n")
	if err != nil {
		t.Fatalf("Decode(integer spelling) returned error: %v", err)
	}
	if got["answer"] != (Value{Type: "integer", Value: "1_000"}) {
		t.Fatalf("Decode(integer spelling) = %v", got["answer"])
	}
}

func TestDecodeScalars(t *testing.T) {
	tests := []struct {
		name, input string
		want        Value
	}{
		{"true", "value = true", Value{Type: "bool", Value: "true"}},
		{"false", "value = false", Value{Type: "bool", Value: "false"}},
		{"hex", "value = -0xDEAD_BEEF", Value{Type: "integer", Value: "-0xDEAD_BEEF"}},
		{"octal", "value = 0o755", Value{Type: "integer", Value: "0o755"}},
		{"binary", "value = +0b1010", Value{Type: "integer", Value: "+0b1010"}},
		{"float", "value = 3.1415", Value{Type: "float", Value: "3.1415"}},
		{"exponent", "value = -2.5e+3", Value{Type: "float", Value: "-2.5e+3"}},
		{"special", "value = -inf", Value{Type: "float", Value: "-inf"}},
		{"negative zero", "value = -0.0", Value{Type: "float", Value: "-0.0"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Decode(tt.input)
			if err != nil {
				t.Fatalf("Decode(%q) returned error: %v", tt.input, err)
			}
			if got["value"] != tt.want {
				t.Fatalf("Decode(%q) = %v, want %v", tt.input, got["value"], tt.want)
			}
		})
	}
}

func TestDecodeRejectsMalformedScalars(t *testing.T) {
	inputs := []string{
		"value = True", "value = TRUE", "value = 01", "value = 1__0",
		"value = 0x", "value = 0x_1", "value = 0b102", "value = 0o8",
		"value = 9223372036854775808", "value = 1.0.0", "value = 1e",
		"value = .5", "value = 01.0", "value = inf.0", "value = nanfoo",
	}
	for _, input := range inputs {
		if _, err := Decode(input); err == nil {
			t.Errorf("Decode(%q) accepted malformed scalar", input)
		}
	}
}

func TestDecodeStrings(t *testing.T) {
	tests := []struct {
		name, input, want string
	}{
		{"basic", `message = "hello"`, "hello"},
		{"escapes", `message = "\b\t\n\f\r\"\\"`, "\b\t\n\f\r\"\\"},
		{"unicode", `message = "\u03B1\U0001F600"`, "α😀"},
		{"literal", `message = 'a\nb#c'`, `a\nb#c`},
		{"multiline basic", "message = \"\"\"hello\nworld\"\"\"", "hello\nworld"},
		{"multiline literal", "message = '''hello\nworld'''", "hello\nworld"},
		{"continuation", "message = \"first\\\n  second\"", "firstsecond"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Decode(tt.input)
			if err != nil {
				t.Fatalf("Decode(%q) returned error: %v", tt.input, err)
			}
			if got["message"] != (Value{Type: "string", Value: tt.want}) {
				t.Fatalf("Decode(%q) = %v, want %q", tt.input, got["message"], tt.want)
			}
		})
	}
}

func TestDecodeRejectsMalformedStrings(t *testing.T) {
	inputs := []string{
		`message = "bad\q"`,
		`message = "bad\uD800"`,
		`message = "bad`,
		`message = "bad` + "\nnext = 1",
		`message = "bad` + string([]byte{0x01}) + `"`,
		`message = '''bad`,
	}
	for _, input := range inputs {
		if _, err := Decode(input); err == nil {
			t.Errorf("Decode(%q) accepted malformed string", input)
		}
	}
}

func TestDecodeCommentsAndLineBoundaries(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  Value
	}{
		{name: "attached comment", input: "value=42# comment", want: Value{Type: "integer", Value: "42"}},
		{name: "hash in basic string", input: `value = "a#b" # comment`, want: Value{Type: "string", Value: "a#b"}},
		{name: "hash in literal string", input: `value = '#b' # comment`, want: Value{Type: "string", Value: "#b"}},
		{name: "tabs are whitespace", input: "\tvalue\t=\ttrue\t# comment", want: Value{Type: "bool", Value: "true"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := Decode(tt.input)
			if err != nil {
				t.Fatalf("Decode(%q) returned error: %v", tt.input, err)
			}
			if got["value"] != tt.want {
				t.Fatalf("Decode(%q) = %v, want %v", tt.input, got["value"], tt.want)
			}
		})
	}
}

func TestDecodeRejectsLexicalBoundaryViolations(t *testing.T) {
	tests := []struct {
		name  string
		input string
	}{
		{name: "adjacent statements", input: "a = 1 b = 2"},
		{name: "lone carriage return", input: "a = 1\rb = 2"},
		{name: "null", input: "# bad" + string([]byte{0})},
		{name: "vertical tab", input: "a = 1" + string([]byte{0x0b})},
		{name: "form feed", input: "# bad" + string([]byte{0x0c})},
		{name: "delete", input: "# bad" + string([]byte{0x7f})},
		{name: "invalid UTF-8", input: string([]byte{'a', '=', ' ', 0xff})},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := Decode(tt.input); err == nil {
				t.Fatalf("Decode(%q) accepted invalid lexical boundary", tt.input)
			}
		})
	}
}
